# -*- coding: utf-8 -*-
"""Rhythm strips and rhythm vignettes, pool B -- SUPRAVENTRICULAR rhythms described in words
(CMS I Exam 5, Lecture 29 deck).

Each stem is a patient whose rhythm is DESCRIBED (rate, regularity, P waves and their relation to
the QRS, PR interval, QRS width), as the course said most exam rhythm questions will be. Lead-ins
spread over the rhythm, its cause, the describing features, the test and the next step.

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation. Slides only; the caps and
contested-slide decisions in cms_e5l29_scope.py hold here too.
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e5rhy_scope import *


def V(topic, io, q, opts, cite, slot, lead):
    d = Q(topic, io, q, opts, cite)
    d["slot"] = slot
    d["lead"] = lead
    return d


SIN = "Sinus rhythms"
SSS = "Sick sinus syndrome"
ATR = "Atrial tachycardia"
SVT = "Nodal and reentrant tachycardia"
WPW = "Wolff-Parkinson-White syndrome"
FLU = "Atrial flutter"
AFB = "Atrial fibrillation"
PRE = "Premature beats"
JUN = "Junctional rhythm"

